import React from 'react';
import {
  Avatar,
  Box,
  Card,
  CardContent,
  Typography,
  Chip,
  Link,
  Divider,
} from '@mui/material';
import { LockOutline, WorkHistory } from '@mui/icons-material';
import Swal from 'sweetalert2';
import { useUser } from '../../Context/userContext';

const ProfileCard = () => {
  const { user } = useUser();



  const handleLockOut = () => {
    Swal.fire({
      title: 'คุณแน่ใจหรือไม่?',
      text: 'การกระทำนี้ไม่สามารถย้อนกลับได้!',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'ใช่, ดำเนินการต่อ!',
      cancelButtonText: 'ยกเลิก',
    }).then((result) => {
      if (result.isConfirmed) {
        localStorage.removeItem('token');
        localStorage.removeItem('profile');
        Swal.fire('ดำเนินการแล้ว!', 'คุณได้ยืนยันการกระทำนี้แล้ว', 'success');
        window.location.replace('/')
        // ทำสิ่งที่ต้องการหลังจากยืนยัน
      }
    });
  };

  return (
    <Box sx={{ display: 'flex', justifyContent: 'center', mt: 5 }}>
      <Card sx={{ width: '100%', padding: 2, margin: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
          <Avatar
            alt={user?.fullname}
            src={'https://i.pravatar.cc/150?img=47'}
            sx={{ width: 100, height: 100 }}
          />
        </Box>
        <CardContent>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
            <Box sx={{ flex: 1 }}>
              <Typography variant="h6" gutterBottom>ข้อมูลผู้ใช้งาน</Typography>
              <Divider sx={{ mb: 2 }} />

              <Info label="ชื่อผู้ใช้" value={user?.username} />
              <Info label="ชื่อพนักงาน" value={user?.fullname} />
              <Info label="รหัสพนักงาน" value={user?.employee_id} />
              <Info label="รหัสบริษัท" value={user?.company_id} />
              <Info label="ชื่อบริษัท" value={user?.name} />
              <Info label="ตำแหน่ง" value={user?.position} />
              <Info label="แผนก" value={user?.department} />
              <Info label="LINE Group ID" value={user?.line_group_id} />
              {/* <Info label="Last Login" value={new Date(user?.last_login).toLocaleString()} /> */}
              <Info
                label="Dashboard URL"
                value={
                  <Link href={user?.dashboard_url} target="_blank" rel="noopener">
                    {user?.dashboard_url}
                  </Link>
                }
              />
            </Box>
            {/* <Typography variant="h6" align="center">
              รหัส : {user?.employee_id}
            </Typography>
            <Typography variant="h6" align="center">
              {user?.fullname}
            </Typography>
            <Typography color="text.secondary" align="center">
              {user?.position} - {user?.department}
            </Typography> */}
            {/* <Chip
              label={user.sta}
              color={user.status === 'กำลังทำงาน' ? 'success' : 'default'}
              sx={{ mt: 1 }}
            /> */}
            <button onClick={() => handleLockOut()} style={{ display: 'flex', alignItems: 'center', flex: 2, justifyContent: 'center', padding: 5, margin: 15 }}
              className='btn btn-primary' title='เข้างาน'  ><LockOutline></LockOutline> ออกจากระบบ</button>
          </div>

        </CardContent>
      </Card>
    </Box>
  );
};
// คอมโพเนนต์ย่อยสำหรับแสดง label + value
const Info = ({ label, value }: { label: string; value: React.ReactNode }) => (
  <Box sx={{ mb: 1.5, textAlign: 'left' }}>
    <Typography variant="body2" color="text.secondary">
      {label} {value}
    </Typography>
  </Box>
);
export default ProfileCard;
